(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('equation').textContent='—';$('r2').textContent='—';$('pred').textContent='—';$('npts').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const lines=$('pairs').value.split(/\n+/).map(x=>x.trim()).filter(Boolean);const pts=[];for(const line of lines){const parts=line.split(/[;,\t ]+/).filter(Boolean).map(Number);if(parts.length>=2&&parts.slice(0,2).every(Number.isFinite))pts.push([parts[0],parts[1]])}if(pts.length<2)throw 0;const n=pts.length,sx=pts.reduce((a,p)=>a+p[0],0),sy=pts.reduce((a,p)=>a+p[1],0),sxx=pts.reduce((a,p)=>a+p[0]*p[0],0),sxy=pts.reduce((a,p)=>a+p[0]*p[1],0);const den=n*sxx-sx*sx;if(Math.abs(den)<1e-15)throw 0;const slope=(n*sxy-sx*sy)/den,inter=(sy-slope*sx)/n;const ybar=sy/n;let ssr=0,sst=0;const rows=pts.map(p=>{const fit=slope*p[0]+inter,res=p[1]-fit;ssr+=res*res;sst+=(p[1]-ybar)**2;return [p[0],p[1],fit,res]});const R2=sst>0?1-ssr/sst:1,uy=num('unknown'),ux=slope!==0?(uy-inter)/slope:NaN;$('equation').textContent='y = '+fmt(slope,6)+'x '+(inter>=0?'+ ':'− ')+fmt(Math.abs(inter),6);$('r2').textContent=fmt(R2,6);$('pred').textContent=Number.isFinite(ux)?fmt(ux,6):'Unavailable';$('npts').textContent=n;$('calRows').innerHTML=rows.map(p=>'<tr><td>'+fmt(p[0],6)+'</td><td>'+fmt(p[1],6)+'</td><td>'+fmt(p[2],6)+'</td><td>'+fmt(p[3],6)+'</td></tr>').join('');$('note').textContent='This fits an unconstrained ordinary least-squares straight line. Inspect residuals and validate the calibration range before quantifying unknowns.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
